SELECT stock_qty_bucket, last_launch_date, stddev_cost FROM (SELECT CASE WHEN stock_qty >= 434 THEN 'high' WHEN stock_qty >= 54 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, MAX(launch_date) AS last_launch_date, ROUND(STDDEV(cost), 2) AS stddev_cost FROM products GROUP BY CASE WHEN stock_qty >= 434 THEN 'high' WHEN stock_qty >= 54 THEN 'mid' ELSE 'low' END) AS t WHERE stddev_cost >= 22 ORDER BY stock_qty_bucket LIMIT 10
